/*VE*/HL.ve={"1": [{"id": "ve-sd-01a", "ab": "A", "ten": "Hello, Hello!", "ten_zh": "你好你好！", "en": ["Hello, hello, everyone!", "Hello, teacher! Class is fun!", "What's your name? What's your name?", "Leo, Leo, that's my name!"], "zh": ["你好你好，大家好！", "老师老师，早上好！", "你叫什么名字呀？", "我叫Leo，Leo呀！"], "py": ["nǐ hǎo nǐ hǎo, dà jiā hǎo!", "lǎo shī lǎo shī, zǎo shang hǎo!", "nǐ jiào shén me míng zi ya?", "wǒ jiào Leo, Leo ya!"]}, {"id": "ve-sd-01b", "ab": "B", "ten": "Goodbye, Goodbye!", "ten_zh": "再见，再见！", "en": ["Goodbye, goodbye, everyone!", "One, two, three… school is done!", "See you tomorrow, Leo and Anna!", "Goodbye, teacher! Let's go!"], "zh": ["大家再见，再见啦！", "一二三，放学啦！", "Leo，Anna，明天见！", "老师老师，再见！"], "py": ["dà jiā zài jiàn, zài jiàn la!", "yī èr sān, fàng xué la!", "Leo, Anna, míng tiān jiàn!", "lǎo shī lǎo shī, zài jiàn!"]}], "2": [{"id": "ve-sd-02a", "ab": "A", "ten": "Fingers and Toes", "ten_zh": "手指和脚趾", "en": ["Wiggle your fingers! Count them, please!", "Ten fingers! Wiggle, squeeze!", "Stretch your arms! Up, up, high!", "Two long arms! Touch the sky!", "Wiggle your toes! Wiggle your toes!", "Ten little toes, and one big nose!", "How old are you?", "I'm nine! Nine fingers! What about you?"], "zh": ["动动手指，数一数！", "十个手指，捏一捏！", "伸伸胳膊，高高举！", "两只胳膊，摸到天！", "动动脚趾，动一动！", "十个脚趾，一个鼻子！", "你几岁？", "我九岁！九个手指！你呢？"], "py": ["dòng dòng shǒu zhǐ, shǔ yi shǔ!", "shí ge shǒu zhǐ, niē yi niē!", "shēn shēn gē bo, gāo gāo jǔ!", "liǎng zhī gē bo, mō dào tiān!", "dòng dòng jiǎo zhǐ, dòng yi dòng!", "shí ge jiǎo zhǐ, yí ge bí zi!", "nǐ jǐ suì?", "wǒ jiǔ suì! jiǔ ge shǒu zhǐ! nǐ ne?"]}, {"id": "ve-sd-02b", "ab": "B", "ten": "Goodbye, Class!", "ten_zh": "同学们，再见！", "en": ["Wave goodbye! Wave to the class!", "See you tomorrow! Time goes fast!", "Oops! I'm sorry! I dropped my pen!", "No problem! Pick it up again!", "Kids, kids, write your name!", "I write it! You write the same!", "See you tomorrow!", "Goodbye, Mrs Lan! See you tomorrow!"], "zh": ["挥挥手，再见啦！", "明天见！快快来吧！", "哎呀！对不起！笔掉了！", "没关系！捡起来！", "小朋友，写名字！", "我写写，你也写！", "明天见！", "老师再见！明天见！"], "py": ["huī huī shǒu, zài jiàn la!", "míng tiān jiàn! kuài kuài lái ba!", "āi yā! duì bu qǐ! bǐ diào le!", "méi guān xi! jiǎn qǐ lai!", "xiǎo péng you, xiě míng zi!", "wǒ xiě xiě, nǐ yě xiě!", "míng tiān jiàn!", "lǎo shī zài jiàn! míng tiān jiàn!"]}], "3": [{"id": "ve-sd-03a", "ab": "A", "ten": "Shake Your Body", "ten_zh": "动动身体", "en": ["Shake your body! Shake, shake, shake!", "Shake your shoulders! Wiggle like a snake!", "Bend your knees! Down, down, down!", "Long legs, jump up from the ground!", "Touch your hair! Is it long?", "Yes, my hair is long and strong!", "Touch your toes!", "I touch my toes… and up I go!"], "zh": ["动动身体，扭一扭！", "摇摇肩膀，扭扭扭！", "弯弯膝盖，蹲下去！", "长长的腿，跳起来！", "摸摸头发，长不长？", "我的头发长又长！", "摸脚趾！", "摸到脚趾，站起来！"], "py": ["dòng dòng shēn tǐ, niǔ yi niǔ!", "yáo yáo jiān bǎng, niǔ niǔ niǔ!", "wān wān xī gài, dūn xià qù!", "cháng cháng de tuǐ, tiào qǐ lai!", "mō mō tóu fa, cháng bù cháng?", "wǒ de tóu fa cháng yòu cháng!", "mō jiǎo zhǐ!", "mō dào jiǎo zhǐ, zhàn qǐ lai!"]}, {"id": "ve-sd-03b", "ab": "B", "ten": "Which Is Bigger?", "ten_zh": "哪个大？", "en": ["Which is bigger? Nine or ten?", "Ten is bigger! Count again!", "Which is smaller? Seven or nine?", "Seven is smaller! Stand in line!", "I am nine! What about you?", "I'm nine! Really? Me too!", "How old are you?", "I'm ten! I'm ten! Bigger than two!"], "zh": ["九和十，哪个大？", "十比九大！再数吧！", "七和九，哪个小？", "七比九小！排排好！", "我九岁！你呢？", "九岁！真的？我也是！", "你几岁？", "我十岁！十比二大！"], "py": ["jiǔ hé shí, nǎ ge dà?", "shí bǐ jiǔ dà! zài shǔ ba!", "qī hé jiǔ, nǎ ge xiǎo?", "qī bǐ jiǔ xiǎo! pái pái hǎo!", "wǒ jiǔ suì! nǐ ne?", "jiǔ suì! zhēn de? wǒ yě shì!", "nǐ jǐ suì?", "wǒ shí suì! shí bǐ èr dà!"]}], "5": [{"id": "ve-sd-05a", "ab": "A", "ten": "My Big Brother", "ten_zh": "我的哥哥", "en": ["My older brother is bigger than me!", "My younger sister is smaller, see?", "My uncle is Chinese! Ni hao!", "My aunt is Chinese, too! Wow!", "Look at the girl! Who is she?", "She's my older sister! She loves me!", "Who is older?", "I'm younger, I sit on his shoulder!"], "zh": ["我哥哥比我大！", "我妹妹比我小！", "我叔叔是中国人，你好！", "我阿姨也是！哇！", "看那个女孩，她是谁？", "她是我姐姐！她爱我！", "谁大？", "我小！我坐在他肩膀上！"], "py": ["wǒ gē ge bǐ wǒ dà!", "wǒ mèi mei bǐ wǒ xiǎo!", "wǒ shū shu shì zhōng guó rén, nǐ hǎo!", "wǒ ā yí yě shì! wā!", "kàn nà ge nǚ hái, tā shì shéi?", "tā shì wǒ jiě jie! tā ài wǒ!", "shéi dà?", "wǒ xiǎo! wǒ zuò zài tā jiān bǎng shàng!"]}, {"id": "ve-sd-05b", "ab": "B", "ten": "We Learn Chinese", "ten_zh": "我们学中文", "en": ["We learn English! We learn Chinese!", "We can say it! Listen, please!", "Bông is Vietnamese! Xiaomei is Chinese!", "We are friends! Say cheese!", "Look, look at my family photo!", "I love them! I love them so!", "What do you learn?", "I learn Chinese! Now it's your turn!"], "zh": ["我们学英语！我们学中文！", "我们会说！请你听！", "Bông是越南人，小美是中国人！", "我们是朋友！拍照片！", "看看我的家庭照片！", "我爱他们！很爱他们！", "你学什么？", "我学中文！该你了！"], "py": ["wǒ men xué yīng yǔ! wǒ men xué zhōng wén!", "wǒ men huì shuō! qǐng nǐ tīng!", "Bông shì yuè nán rén, xiǎo měi shì zhōng guó rén!", "wǒ men shì péng you! pāi zhào piàn!", "kàn kan wǒ de jiā tíng zhào piàn!", "wǒ ài tā men! hěn ài tā men!", "nǐ xué shén me?", "wǒ xué zhōng wén! gāi nǐ le!"]}], "6": [{"id": "ve-sd-06a", "ab": "A", "ten": "Close Your Eyes!", "ten_zh": "闭上眼睛！", "en": ["Close your eyes… and count to three!", "Open your eyes! What do you see?", "Raise your right hand! Up, up, high!", "Wave your right hand and say hi!", "What's your favourite toy? Tell me, please!", "My toy bear! I squeeze and squeeze!", "How do you feel?", "I feel excited, from head to heel!"], "zh": ["闭上眼睛，数到三！", "睁开眼睛，看见什么？", "举起右手，高高的！", "挥挥右手，说你好！", "你最喜欢什么玩具？", "我的玩具熊！抱一抱！", "你感觉怎么样？", "我很兴奋！从头到脚！"], "py": ["bì shang yǎn jing, shǔ dào sān!", "zhēng kāi yǎn jing, kàn jiàn shén me?", "jǔ qǐ yòu shǒu, gāo gāo de!", "huī huī yòu shǒu, shuō nǐ hǎo!", "nǐ zuì xǐ huan shén me wán jù?", "wǒ de wán jù xióng! bào yi bào!", "nǐ gǎn jué zěn me yàng?", "wǒ hěn xīng fèn! cóng tóu dào jiǎo!"]}, {"id": "ve-sd-06b", "ab": "B", "ten": "Bedtime", "ten_zh": "睡觉啦", "en": ["Thirsty? Drink your water, please.", "Hungry? Have some bread and cheese!", "Now it's night! Go to bed!", "Read me a story! Rest my head!", "Close your eyes… sleep, sleep tight.", "Good night, mummy! Turn off the light!", "Are you sleepy?", "Yes, I'm sleepy! Byebye, buddy!"], "zh": ["渴了吗？喝点水！", "饿了吗？吃面包！", "天黑了！睡觉吧！", "讲故事！讲一个吧！", "闭上眼睛，快睡觉！", "妈妈晚安！关灯吧！", "你困了吗？", "困了！晚安，大家！"], "py": ["kě le ma? hē diǎn shuǐ!", "è le ma? chī miàn bāo!", "tiān hēi le! shuì jiào ba!", "jiǎng gù shi! jiǎng yí ge ba!", "bì shang yǎn jing, kuài shuì jiào!", "mā ma wǎn ān! guān dēng ba!", "nǐ kùn le ma?", "kùn le! wǎn ān, dà jiā!"]}], "7": [{"id": "ve-sd-07a", "ab": "A", "ten": "Make a Line!", "ten_zh": "排好队！", "en": ["Make a line! Stand up tall!", "Walk, walk, walk! And don't fall!", "Look at the board! What are those?", "Those are letters, in two rows!", "Open your book! Read with me!", "Read the letters! A, B, C!", "Write your name!", "Big letters! That's my name!"], "zh": ["排好队，站直站好！", "走走走，别摔倒！", "看黑板！那些是什么？", "那些是字母，两排呢！", "打开书，跟我读！", "读字母，A、B、C！", "写名字！", "大大的字母！我的名字！"], "py": ["pái hǎo duì, zhàn zhí zhàn hǎo!", "zǒu zǒu zǒu, bié shuāi dǎo!", "kàn hēi bǎn! nà xiē shì shén me?", "nà xiē shì zì mǔ, liǎng pái ne!", "dǎ kāi shū, gēn wǒ dú!", "dú zì mǔ, A, B, C!", "xiě míng zi!", "dà dà de zì mǔ! wǒ de míng zi!"]}, {"id": "ve-sd-07b", "ab": "B", "ten": "Tidy Up!", "ten_zh": "收拾好！", "en": ["Put away your pencil, please!", "Crayons, scissors, and all these!", "Put the glue back on the shelf!", "Tidy, tidy, all by myself!", "Byebye, keyboard! Byebye, mouse!", "School is done! Let's go to my house!", "What's in your bag?", "A pencil, a ruler, and a name tag!"], "zh": ["请收好你的铅笔！", "蜡笔、剪刀，还有这些！", "把胶水放回去！", "收拾好，我自己来！", "键盘再见！鼠标再见！", "下课了！去我家玩吧！", "包里有什么？", "铅笔、尺子、名字卡！"], "py": ["qǐng shōu hǎo nǐ de qiān bǐ!", "là bǐ, jiǎn dāo, hái yǒu zhè xiē!", "bǎ jiāo shuǐ fàng huí qu!", "shōu shi hǎo, wǒ zì jǐ lái!", "jiàn pán zài jiàn! shǔ biāo zài jiàn!", "xià kè le! qù wǒ jiā wán ba!", "bāo lǐ yǒu shén me?", "qiān bǐ, chǐ zi, míng zi kǎ!"]}], "8": [{"id": "ve-sd-08a", "ab": "A", "ten": "Wings, Legs and Tails", "ten_zh": "翅膀、腿和尾巴", "en": ["A duck has two wings! Flap, flap, flap!", "I have two arms! Clap, clap, clap!", "A frog has long legs! Hop, hop, hop!", "I have long legs! I can't stop!", "A mouse has a tail! Wiggle, wiggle!", "I have no tail! Giggle, giggle!", "Can you fly?", "No, I can't! No wings! But I try!"], "zh": ["鸭子有两只翅膀！拍拍拍！", "我有两只胳膊！拍拍拍！", "青蛙有长腿！跳跳跳！", "我有长腿！停不下！", "老鼠有尾巴！摇一摇！", "我没有尾巴！哈哈笑！", "你会飞吗？", "不会！没有翅膀！试试吧！"], "py": ["yā zi yǒu liǎng zhī chì bǎng! pāi pāi pāi!", "wǒ yǒu liǎng zhī gē bo! pāi pāi pāi!", "qīng wā yǒu cháng tuǐ! tiào tiào tiào!", "wǒ yǒu cháng tuǐ! tíng bú xià!", "lǎo shǔ yǒu wěi ba! yáo yi yáo!", "wǒ méi yǒu wěi ba! hā hā xiào!", "nǐ huì fēi ma?", "bú huì! méi yǒu chì bǎng! shì shì ba!"]}, {"id": "ve-sd-08b", "ab": "B", "ten": "Lights On, Lights Off", "ten_zh": "开灯，关灯", "en": ["Turn on the lamp in the living room!", "Close the window in the bedroom!", "Bed or chair? Where, oh where?", "Under the table! Right there!", "Knock, knock! Who's at the door?", "It's grandpa! Sit on the floor!", "Where do you sleep?", "In my bedroom! Count the sheep!"], "zh": ["打开客厅的灯！", "关上卧室的窗户！", "在床下还是椅子下？", "在桌子下面！就在那儿！", "咚咚咚！谁在门外？", "是爷爷！快进来！", "你在哪儿睡觉？", "在我的卧室！数小羊！"], "py": ["dǎ kāi kè tīng de dēng!", "guān shàng wò shì de chuāng hu!", "zài chuáng xià hái shi yǐ zi xià?", "zài zhuō zi xià miàn! jiù zài nàr!", "dōng dong dōng! shéi zài mén wài?", "shì yé ye! kuài jìn lái!", "nǐ zài nǎr shuì jiào?", "zài wǒ de wò shì! shǔ xiǎo yáng!"]}], "9": [{"id": "ve-sd-09a", "ab": "A", "ten": "Stand Up Tall!", "ten_zh": "站得高高！", "en": ["The polar bear is big and tall!", "Stand up tall! Don't fall, don't fall!", "Row the boat! Row, row, row!", "In the forest, slow, slow, slow!", "The frog says hop! The duck says quack!", "Hop to the forest, and hop back!", "Are you tall?", "Yes, I'm tall! Taller than a ball!"], "zh": ["北极熊又大又高！", "站得高高！别倒！", "划船！快划船！", "森林里面，慢慢划船！", "青蛙跳跳，鸭子嘎嘎！", "跳进森林，再跳回家！", "你高吗？", "我很高！比球还高！"], "py": ["běi jí xióng yòu dà yòu gāo!", "zhàn de gāo gāo! bié dào!", "huá chuán! kuài huá chuán!", "sēn lín lǐ miàn, màn màn huá chuán!", "qīng wā tiào tiào, yā zi gā gā!", "tiào jìn sēn lín, zài tiào huí jiā!", "nǐ gāo ma?", "wǒ hěn gāo! bǐ qiú hái gāo!"]}, {"id": "ve-sd-09b", "ab": "B", "ten": "Can or Can't?", "ten_zh": "会不会？", "en": ["Can a fish walk? No, it can't!", "Can a duck swim? Yes, it can!", "Can a polar bear fly? No, no!", "It can swim and walk in the snow!", "Can you hop, hop like a frog?", "Yes, I can! Hop on a log!", "Can you swim?", "Yes, I can! Let's jump in!"], "zh": ["鱼会走路吗？不会！", "鸭子会游泳吗？会！", "北极熊会飞吗？不会！", "它会游泳，会在雪里走！", "你会像青蛙一样跳吗？", "会！跳到木头上！", "你会游泳吗？", "会！我会！跳下去吧！"], "py": ["yú huì zǒu lù ma? bú huì!", "yā zi huì yóu yǒng ma? huì!", "běi jí xióng huì fēi ma? bú huì!", "tā huì yóu yǒng, huì zài xuě lǐ zǒu!", "nǐ huì xiàng qīng wā yí yàng tiào ma?", "huì! tiào dào mù tou shàng!", "nǐ huì yóu yǒng ma?", "huì! wǒ huì! tiào xià qù ba!"]}], "10": [{"id": "ve-sd-10a", "ab": "A", "ten": "Snack Time!", "ten_zh": "吃点心啦！", "en": ["Look at the burger! It looks nice!", "Yum! I want it! One, no, twice!", "Ice cream, ice cream! Cold and sweet!", "Chips and juice! Let's eat!", "Tell me: what's your favourite food?", "Burgers! Burgers! I'm in a good mood!", "Are you hungry?", "Yes! I'm hungry! Food for my tummy!"], "zh": ["看这个汉堡，看起来好吃！", "嗯！我想要！要两个！", "冰淇淋，冰淇淋！又冷又甜！", "薯条果汁，开吃啦！", "你最喜欢什么食物？", "汉堡！汉堡！我很开心！", "你饿吗？", "饿了！我要吃饭啦！"], "py": ["kàn zhè ge hàn bǎo, kàn qǐ lai hǎo chī!", "ǹg! wǒ xiǎng yào! yào liǎng ge!", "bīng qí lín, bīng qí lín! yòu lěng yòu tián!", "shǔ tiáo guǒ zhī, kāi chī la!", "nǐ zuì xǐ huan shén me shí wù?", "hàn bǎo! hàn bǎo! wǒ hěn kāi xīn!", "nǐ è ma?", "è le! wǒ yào chī fàn la!"]}, {"id": "ve-sd-10b", "ab": "B", "ten": "Noodles, Please", "ten_zh": "我要面条", "en": ["Noodles, noodles, long and thin!", "Slurp, slurp… noodles on my chin!", "Candy? Candy? No, thank you!", "Fruit is good! A banana, too!", "Cross the candy! Tick the bread!", "Good job, good job! The teacher said!", "What do you want?", "I want juice, please! Thank you, aunt!"], "zh": ["面条面条，长又细！", "吸溜吸溜，吃下去！", "糖果？糖果？不要，谢谢！", "水果好！香蕉也好！", "糖果画叉，面包打勾！", "老师说：做得好！", "你要什么？", "我要果汁！谢谢阿姨！"], "py": ["miàn tiáo miàn tiáo, cháng yòu xì!", "xī liū xī liū, chī xià qù!", "táng guǒ? táng guǒ? bú yào, xiè xie!", "shuǐ guǒ hǎo! xiāng jiāo yě hǎo!", "táng guǒ huà chā, miàn bāo dǎ gōu!", "lǎo shī shuō: zuò de hǎo!", "nǐ yào shén me?", "wǒ yào guǒ zhī! xiè xie ā yí!"]}], "11": [{"id": "ve-sd-11a", "ab": "A", "ten": "Get Dressed!", "ten_zh": "穿好衣服！", "en": ["Put on your coat! Arms in, in!", "Put on your scarf! A big, big grin!", "Put on your hat! On your head!", "A hat on my head… blue and red!", "Open your umbrella! Up, up, up!", "Drop, drop, drop! Rain in my cup!", "Let's go out!", "Coat, scarf, hat… now we shout!"], "zh": ["穿上外套！胳膊伸进去！", "戴上围巾！笑嘻嘻！", "戴上帽子！戴头上！", "帽子戴头上，红又蓝！", "打开雨伞，举高高！", "滴答滴答，雨掉下来！", "我们出去吧！", "外套围巾帽子，出发吧！"], "py": ["chuān shàng wài tào! gē bo shēn jìn qù!", "dài shàng wéi jīn! xiào xī xī!", "dài shàng mào zi! dài tóu shàng!", "mào zi dài tóu shàng, hóng yòu lán!", "dǎ kāi yǔ sǎn, jǔ gāo gāo!", "dī dā dī dā, yǔ diào xià lái!", "wǒ men chū qù ba!", "wài tào wéi jīn mào zi, chū fā ba!"]}, {"id": "ve-sd-11b", "ab": "B", "ten": "Rainy Day", "ten_zh": "下雨天", "en": ["Is it cloudy? Is it wet?", "Stay at home! Don't go out yet!", "Look! The sun! The clouds go away!", "Take your umbrella! Let's go and play!", "What's the weather like today?", "It's cold! Coat and scarf, ok?", "Goodbye, goodbye!", "Take your umbrella! Keep dry!"], "zh": ["今天多云？下雨吗？", "在家玩！先别出去！", "看！太阳！云走了！", "带上雨伞，出去玩！", "今天天气怎么样？", "很冷！穿外套，戴围巾！", "再见啦！", "带上雨伞，别淋湿啦！"], "py": ["jīn tiān duō yún? xià yǔ ma?", "zài jiā wán! xiān bié chū qù!", "kàn! tài yang! yún zǒu le!", "dài shàng yǔ sǎn, chū qù wán!", "jīn tiān tiān qì zěn me yàng?", "hěn lěng! chuān wài tào, dài wéi jīn!", "zài jiàn la!", "dài shàng yǔ sǎn, bié lín shī la!"]}], "12": [{"id": "ve-sd-12a", "ab": "A", "ten": "Let's Go Out!", "ten_zh": "我们出去吧！", "en": ["It's snowing! Let's go out!", "Make a snowman! Jump and shout!", "Give him a hat and a scarf, too!", "A carrot nose, and eyes of blue!", "It's cold! It's cold! Brr, brr, brr!", "Put on your coat! A coat with fur!", "Are you cold?", "No! I'm warm in my scarf of gold!"], "zh": ["下雪了！我们出去！", "堆雪人！跳起来！", "给他戴帽子，戴围巾！", "胡萝卜鼻子，蓝眼睛！", "好冷！好冷！发抖了！", "穿上外套！毛毛的！", "你冷吗？", "不冷！我有金色的围巾！"], "py": ["xià xuě le! wǒ men chū qù!", "duī xuě rén! tiào qǐ lai!", "gěi tā dài mào zi, dài wéi jīn!", "hú luó bo bí zi, lán yǎn jing!", "hǎo lěng! hǎo lěng! fā dǒu le!", "chuān shàng wài tào! máo mao de!", "nǐ lěng ma?", "bù lěng! wǒ yǒu jīn sè de wéi jīn!"]}, {"id": "ve-sd-12b", "ab": "B", "ten": "Clothes Parade", "ten_zh": "服装秀", "en": ["Jeans and trousers! Who wears those?", "Leo does! And red socks on his toes!", "A gold dress! A silver skirt!", "A brown jacket and a white shirt!", "Bounce the ball! One, two, three!", "In my shorts! So cool! Look at me!", "What are you wearing?", "I'm wearing my jeans! And you're staring!"], "zh": ["牛仔裤、裤子，谁穿的？", "Leo穿！还有红袜子！", "金色裙子！银色短裙！", "棕色夹克，白衬衫！", "拍球！一、二、三！", "穿短裤，真酷！看我！", "你穿什么？", "我穿牛仔裤！你在看我！"], "py": ["niú zǎi kù, kù zi, shéi chuān de?", "Leo chuān! hái yǒu hóng wà zi!", "jīn sè qún zi! yín sè duǎn qún!", "zōng sè jiā kè, bái chèn shān!", "pāi qiú! yī, èr, sān!", "chuān duǎn kù, zhēn kù! kàn wǒ!", "nǐ chuān shén me?", "wǒ chuān niú zǎi kù! nǐ zài kàn wǒ!"]}]};

